package com.sap.bfx.definition;import com.fasterxml.jackson.annotation.JsonProperty;import com.sap.bfx.utils.EnumUtils;import com.sap.bfx.utils.Identifier;public enum AttachmentCardinality implements Identifier {    @JsonProperty("single")    Single("single"),    @JsonProperty("multiple")    Multiple("multiple");    private final String identifier;    /**     * @param identifier     */    AttachmentCardinality(String identifier) {        this.identifier = identifier;    }    /**     * @param identifier     * @return     */    public static AttachmentCardinality mapUploadType(String identifier) {        return EnumUtils.valueById(AttachmentCardinality.class, identifier, AttachmentCardinality.Single);    }    /**     * @return     */    @Override    public java.lang.String getIdentifier() {        return this.identifier;    }}